import { computed } from '@reatom/core'
import { HEIGHT, BUFFER, WIDTH, previewCells, type PieceType } from '../game/logic'
import type { TetrisModel } from '../game/model'

const COLORS: Record<PieceType, string> = {
  I: '#22d3ee',
  O: '#facc15',
  T: '#a855f7',
  S: '#22c55e',
  Z: '#ef4444',
  J: '#3b82f6',
  L: '#f97316',
}

const pieceColors = Object.entries(COLORS)
  .map(([type, color]) => `[data-cell='${type}'] { --c: ${color}; }`)
  .join('\n')

const cellCss = `
  & [data-cell] {
    border-radius: 3px;
  }
  ${pieceColors.replace(/^\[/gm, '& [')}
  & [data-cell]:not([data-cell='']):not([data-cell='ghost']) {
    background: var(--c);
    box-shadow:
      inset 0 0 0 1px rgb(255 255 255 / 0.25),
      inset -3px -3px 0 rgb(0 0 0 / 0.25);
  }
  & [data-cell='ghost'] {
    box-shadow: inset 0 0 0 2px rgb(255 255 255 / 0.35);
  }
`

type Key = 'left' | 'right' | 'cw' | 'ccw' | 'soft' | 'hard' | 'hold' | 'pause' | 'primary'

const KEYMAP: Record<string, Key> = {
  ArrowLeft: 'left',
  KeyA: 'left',
  ArrowRight: 'right',
  KeyD: 'right',
  ArrowUp: 'cw',
  KeyX: 'cw',
  KeyW: 'cw',
  KeyZ: 'ccw',
  ControlLeft: 'ccw',
  ArrowDown: 'soft',
  KeyS: 'soft',
  Space: 'hard',
  KeyC: 'hold',
  ShiftLeft: 'hold',
  ShiftRight: 'hold',
  KeyP: 'pause',
  Escape: 'pause',
  Enter: 'primary',
}

/** Keys that must not auto-repeat when held down. */
const NO_REPEAT = new Set<Key>(['cw', 'ccw', 'hard', 'hold', 'pause', 'primary'])

const runKey = (game: TetrisModel, key: Key) => {
  switch (key) {
    case 'left':
      return game.moveLeft()
    case 'right':
      return game.moveRight()
    case 'cw':
      return game.rotateCW()
    case 'ccw':
      return game.rotateCCW()
    case 'soft':
      return game.softDrop()
    case 'hard':
      return game.hardDrop()
    case 'hold':
      return game.hold()
    case 'pause':
      return game.togglePause()
    case 'primary':
      return game.primary()
  }
}

const Board = ({ game }: { game: TetrisModel }) => {
  const total = WIDTH * (HEIGHT - BUFFER)
  const overlay = computed(() => {
    switch (game.status()) {
      case 'idle':
        return 'Нажмите Enter, чтобы начать'
      case 'paused':
        return 'Пауза'
      case 'over':
        return 'Игра окончена — Enter для новой игры'
      default:
        return ''
    }
  }, `${game.name}.ui.overlay`)

  return (
    <div
      attr:data-status={game.status}
      css={`
        position: relative;
        display: grid;
        grid-template-columns: repeat(${WIDTH}, var(--cell));
        grid-template-rows: repeat(${HEIGHT - BUFFER}, var(--cell));
        gap: 1px;
        padding: 6px;
        background: #0b1020;
        border: 2px solid #334155;
        border-radius: 8px;
        ${cellCss}
        & > [data-cell=''] {
          background: rgb(255 255 255 / 0.03);
        }
        & > [data-overlay] {
          position: absolute;
          inset: 0;
          display: none;
          place-items: center;
          text-align: center;
          padding: 16px;
          font-size: 20px;
          font-weight: 600;
          background: rgb(2 6 23 / 0.72);
          border-radius: 6px;
        }
        &:not([data-status='running']) > [data-overlay] {
          display: grid;
        }
      `}
    >
      {Array.from({ length: total }, (_, i) => (
        <div attr:data-cell={() => game.cells()[i] ?? ''} />
      ))}
      <div attr:data-overlay="">{overlay}</div>
    </div>
  )
}

const MiniPiece = ({ type }: { type: PieceType | null }) => {
  if (!type) return <div css="height: calc(var(--mini) * 2);" />
  const offsets = previewCells(type)
  const minX = Math.min(...offsets.map(([x]) => x))
  const minY = Math.min(...offsets.map(([, y]) => y))
  const w = Math.max(...offsets.map(([x]) => x)) - minX + 1
  const h = Math.max(...offsets.map(([, y]) => y)) - minY + 1
  const filled = new Set(offsets.map(([x, y]) => `${x - minX}:${y - minY}`))
  return (
    <div
      css={`
        display: grid;
        grid-template-columns: repeat(${w}, var(--mini));
        grid-template-rows: repeat(${h}, var(--mini));
        gap: 1px;
        justify-content: center;
        align-content: center;
        height: calc(var(--mini) * 2 + 1px);
        ${cellCss}
      `}
    >
      {Array.from({ length: w * h }, (_, i) => (
        <div attr:data-cell={filled.has(`${i % w}:${Math.floor(i / w)}`) ? type : ''} />
      ))}
    </div>
  )
}

const Panel = ({ title, children }: { title: string; children?: unknown }) => (
  <section
    css={`
      background: #111827;
      border: 1px solid #1f2937;
      border-radius: 8px;
      padding: 10px 12px;
      display: grid;
      gap: 8px;
      & > h2 {
        margin: 0;
        font-size: 12px;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: #94a3b8;
      }
    `}
  >
    <h2>{title}</h2>
    {children}
  </section>
)

const Stat = ({ label, value }: { label: string; value: () => number }) => (
  <div css="display: flex; justify-content: space-between; gap: 16px;">
    <span css="color: #94a3b8;">{label}</span>
    <b css="font-variant-numeric: tabular-nums;">{computed(() => String(value()))}</b>
  </div>
)

const Button = ({ label, onPress }: { label: string; onPress: () => unknown }) => (
  <button
    type="button"
    tabIndex={-1}
    // keep keyboard focus on the game root
    on:mousedown={(e) => e.preventDefault()}
    on:click={() => onPress()}
    css={`
      font: inherit;
      color: inherit;
      background: #1e293b;
      border: 1px solid #334155;
      border-radius: 6px;
      padding: 8px 10px;
      cursor: pointer;
      touch-action: manipulation;
      &:hover {
        background: #273449;
      }
    `}
  >
    {label}
  </button>
)

export const App = ({ game }: { game: TetrisModel }) => {
  const primaryLabel = computed(() => {
    const s = game.status()
    return s === 'running' ? 'Пауза' : s === 'paused' ? 'Продолжить' : 'Новая игра'
  }, `${game.name}.ui.primaryLabel`)

  const onKeyDown = (e: KeyboardEvent) => {
    const key = KEYMAP[e.code]
    if (!key) return
    e.preventDefault()
    if (e.repeat && NO_REPEAT.has(key)) return
    runKey(game, key)
  }

  return (
    <main
      tabIndex={0}
      ref={(el: HTMLElement) => {
        el.focus()
      }}
      on:keydown={onKeyDown}
      on:pointerdown={(e) => (e.currentTarget as HTMLElement).focus()}
      css={`
        --cell: min(28px, calc((100vh - 80px) / 20));
        --mini: 16px;
        min-height: 100vh;
        box-sizing: border-box;
        display: flex;
        justify-content: center;
        align-items: flex-start;
        gap: 16px;
        padding: 24px;
        outline: none;
        color: #e2e8f0;
        font-family: system-ui, sans-serif;
        & > aside {
          display: grid;
          gap: 12px;
          align-content: start;
          width: 160px;
        }
      `}
    >
      <aside>
        <Panel title="Hold (C)">
          {computed(() => (
            <div css={() => ''} attr:data-dim={game.canHold() ? null : ''}>
              <MiniPiece type={game.held()} />
            </div>
          ), `${game.name}.ui.hold`)}
        </Panel>
        <Panel title="Счёт">
          <Stat label="Очки" value={game.score} />
          <Stat label="Рекорд" value={game.bestScore} />
          <Stat label="Линии" value={game.lines} />
          <Stat label="Уровень" value={game.level} />
        </Panel>
        <Panel title="Управление">
          <small css="color: #94a3b8; line-height: 1.6;">
            ← → — сдвиг<br />
            ↑ / X — поворот, Z — назад<br />
            ↓ — мягкий сброс<br />
            Пробел — жёсткий сброс<br />
            C / Shift — hold<br />
            P / Esc — пауза, Enter — старт
          </small>
        </Panel>
      </aside>

      <Board game={game} />

      <aside>
        <Panel title="Далее">
          {computed(() => (
            <div css="display: grid; gap: 10px;">
              {game.queue().map((type) => (
                <MiniPiece type={type} />
              ))}
            </div>
          ), `${game.name}.ui.next`)}
        </Panel>
        <Button label="" onPress={() => game.primary()} />
        <div css="display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px;">
          <Button label="⟲" onPress={() => game.rotateCCW()} />
          <Button label="⤓" onPress={() => game.hardDrop()} />
          <Button label="⟳" onPress={() => game.rotateCW()} />
          <Button label="←" onPress={() => game.moveLeft()} />
          <Button label="↓" onPress={() => game.softDrop()} />
          <Button label="→" onPress={() => game.moveRight()} />
        </div>
        <Button label="Hold" onPress={() => game.hold()} />
      </aside>
    </main>
  )
}

