import { describe, expect, it } from 'vitest'
import { checkInvariants } from './logic'
import { reatomTetris } from './model'

const makeModel = () =>
  reatomTetris('test', {
    persist: false,
    autoplay: false,
    seed: () => 42,
    strict: true,
  })

describe('reatomTetris', () => {
  it('starts idle and starts a game', () => {
    const game = makeModel()
    expect(game.status()).toBe('idle')
    expect(game.cells().length).toBe(200)
    expect(game.cells().every((c) => c === '')).toBe(true)

    game.start(2)
    expect(game.status()).toBe('running')
    expect(game.level()).toBe(2)
    expect(checkInvariants(game.state())).toEqual([])
  })

  it('scores line clears and updates the best score', () => {
    const game = makeModel()
    game.start(1)
    // drop pieces until at least one line is scored
    for (let i = 0; i < 200 && game.lines() === 0; i++) game.hardDrop()
    expect(game.lines()).toBeGreaterThan(0)
    expect(game.score()).toBeGreaterThan(0)
    expect(game.bestScore()).toBe(game.score())
  })

  it('ignores gameplay commands while idle, paused or over', () => {
    const game = makeModel()
    game.moveLeft()
    game.rotateCW()
    game.hardDrop()
    expect(game.status()).toBe('idle')

    game.start(1)
    game.pause()
    const paused = game.state()
    game.moveLeft()
    game.hardDrop()
    expect(game.state()).toBe(paused)

    game.resume()
    for (let i = 0; i < 100 && game.status() === 'running'; i++) game.hardDrop()
    expect(game.status()).toBe('over')
    const over = game.state()
    game.moveLeft()
    game.hardDrop()
    expect(game.state()).toBe(over)
  })

  it('moves, rotates and shows ghost/piece in cells', () => {
    const game = makeModel()
    game.start(1)
    game.rotateCW()
    const { active } = game.state()
    const marked = game.cells().filter((c) => c !== '')
    // piece cells + at least one ghost row beneath
    expect(marked.length).toBeGreaterThanOrEqual(4)
    expect(game.cells().filter((c) => c === 'ghost').length).toBeGreaterThan(0)
    expect(active).not.toBeNull()
    expect(checkInvariants(game.state())).toEqual([])
  })

  it('hold swaps once per piece', () => {
    const game = makeModel()
    game.start(1)
    const first = game.state().active!.type
    const queued = game.state().queue[0]
    game.hold()
    expect(game.held()).toBe(first)
    expect(game.state().active!.type).toBe(queued)
    expect(game.canHold()).toBe(false)
    const before = game.state()
    game.hold()
    expect(game.state()).toBe(before)
  })

  it('primary button toggles start / pause / resume', () => {
    const game = makeModel()
    game.primary()
    expect(game.status()).toBe('running')
    game.primary()
    expect(game.status()).toBe('paused')
    game.primary()
    expect(game.status()).toBe('running')
  })

  it('ticking falls and eventually locks pieces', () => {
    const game = makeModel()
    game.start(1)
    const initialPieces = game.state().pieces
    for (let i = 0; i < 100 && game.state().pieces === initialPieces; i++) game.tick()
    expect(game.state().pieces).toBe(initialPieces + 1)
  })
})

import { describe, expect, it } from 'vitest'
import {
  HEIGHT,
  PIECES,
  QUEUE_SIZE,
  WIDTH,
  checkInvariants,
  collides,
  createGame,
  createIdle,
  emptyBoard,
  gravityMs,
  pieceCells,
  reduce,
  type Board,
  type Cell,
  type Command,
  type GameState,
} from './logic'

const withBoard = (rows: Cell[][], active: GameState['active']): GameState => ({
  ...createIdle(1),
  status: 'running',
  board: rows,
  active,
})

const mutableBoard = (): Cell[][] => emptyBoard().map((r) => [...r])

describe('logic', () => {
  it('is deterministic for the same seed', () => {
    const a = createGame(123)
    const b = createGame(123)
    expect(a).toEqual(b)
    expect(createGame(124).queue).not.toEqual(a.queue)
  })

  it('uses a 7-bag: every 7 pieces contain each type once', () => {
    let s = createGame(99)
    const seen: string[] = [s.active!.type]
    while (seen.length < 21) {
      s = reduce(s, { type: 'hardDrop' })
      if (s.status !== 'running') break
      seen.push(s.active!.type)
    }
    for (let i = 0; i + 7 <= seen.length; i += 7) {
      expect([...seen.slice(i, i + 7)].sort()).toEqual([...PIECES].sort())
    }
  })

  it('all rotations of all pieces are defined and have 4 cells', () => {
    for (const type of PIECES) {
      for (const rotation of [0, 1, 2, 3] as const) {
        expect(pieceCells({ type, rotation, x: 0, y: 0 })).toHaveLength(4)
      }
    }
  })

  it('does not move through walls', () => {
    let s = createGame(1)
    for (let i = 0; i < 20; i++) s = reduce(s, { type: 'left' })
    expect(Math.min(...pieceCells(s.active!).map(([x]) => x))).toBe(0)
    for (let i = 0; i < 20; i++) s = reduce(s, { type: 'right' })
    expect(Math.max(...pieceCells(s.active!).map(([x]) => x))).toBe(WIDTH - 1)
  })

  it('wall-kicks rotations near walls instead of overlapping', () => {
    let s = createGame(5)
    for (let i = 0; i < 20; i++) s = reduce(s, { type: 'left' })
    for (let i = 0; i < 8; i++) {
      s = reduce(s, { type: 'rotate', dir: i % 2 ? 1 : -1 })
      expect(collides(s.board, s.active!)).toBe(false)
    }
  })

  it('clears lines and scores by level', () => {
    const rows = mutableBoard()
    for (let x = 0; x < WIDTH - 4; x++) rows[HEIGHT - 1]![x] = 'J'
    const s = reduce(withBoard(rows, { type: 'I', rotation: 0, x: 6, y: HEIGHT - 2 }), {
      type: 'hardDrop',
    })
    expect(s.lastClear).toBe(1)
    expect(s.lines).toBe(1)
    expect(s.score).toBe(100)
    expect(s.board[HEIGHT - 1]!.every((c) => c === null)).toBe(true)
  })

  it('awards a tetris', () => {
    const rows = mutableBoard()
    for (let y = HEIGHT - 4; y < HEIGHT; y++) for (let x = 1; x < WIDTH; x++) rows[y]![x] = 'L'
    // vertical I (rotation 1 occupies column x+2)
    const s = reduce(withBoard(rows, { type: 'I', rotation: 1, x: -2, y: 2 }), {
      type: 'hardDrop',
    })
    expect(s.lastClear).toBe(4)
    expect(s.score).toBe(800 + (HEIGHT - 4 - 2) * 2)
  })

  it('soft and hard drops give points', () => {
    const s = createGame(3)
    expect(reduce(s, { type: 'softDrop' }).score).toBe(1)
    expect(reduce(s, { type: 'hardDrop' }).score).toBeGreaterThan(0)
  })

  it('hold swaps once per piece', () => {
    let s = createGame(7)
    const first = s.active!.type
    s = reduce(s, { type: 'hold' })
    expect(s.hold).toBe(first)
    expect(s.canHold).toBe(false)
    const again = reduce(s, { type: 'hold' })
    expect(again).toBe(s)
    s = reduce(s, { type: 'hardDrop' })
    expect(s.canHold).toBe(true)
    const swapped = reduce(s, { type: 'hold' })
    expect(swapped.active!.type).toBe(first)
  })

  it('ignores gameplay commands unless running and returns the same object', () => {
    const idle = createIdle(1)
    const commands: Command[] = [
      { type: 'left' },
      { type: 'right' },
      { type: 'rotate', dir: 1 },
      { type: 'softDrop' },
      { type: 'hardDrop' },
      { type: 'hold' },
      { type: 'tick' },
      { type: 'pause' },
      { type: 'resume' },
    ]
    for (const c of commands) expect(reduce(idle, c)).toBe(idle)
    const paused = reduce(createGame(1), { type: 'pause' })
    expect(paused.status).toBe('paused')
    for (const c of commands.filter((c) => c.type !== 'resume')) {
      expect(reduce(paused, c)).toBe(paused)
    }
    expect(reduce(paused, { type: 'resume' }).status).toBe('running')
  })

  it('ends the game when the stack reaches the top and keeps invariants', () => {
    let s = createGame(42)
    let guard = 0
    while (s.status === 'running' && guard++ < 1000) {
      s = reduce(s, { type: 'hardDrop' })
      if (s.status === 'running') expect(checkInvariants(s)).toEqual([])
    }
    expect(s.status).toBe('over')
    expect(s.active).toBeNull()
  })

  it('survives a long random game with invariants intact', () => {
    let s = createGame(2024)
    const types = ['left', 'right', 'rotate', 'softDrop', 'tick', 'hardDrop', 'hold'] as const
    let rnd = 1
    for (let i = 0; i < 20000 && s.status === 'running'; i++) {
      rnd = (rnd * 1103515245 + 12345) >>> 0
      const type = types[rnd % types.length]!
      const cmd: Command = type === 'rotate' ? { type, dir: rnd & 1 ? 1 : -1 } : { type }
      s = reduce(s, cmd)
      expect(checkInvariants(s)).toEqual([])
    }
    expect(s.queue.length).toBeGreaterThanOrEqual(QUEUE_SIZE)
  })

  it('never mutates the previous state', () => {
    const s = createGame(11)
    const frozen = JSON.stringify(s)
    reduce(s, { type: 'hardDrop' })
    reduce(s, { type: 'left' })
    reduce(s, { type: 'hold' })
    expect(JSON.stringify(s)).toBe(frozen)
  })

  it('sanitizes bad seeds and levels', () => {
    expect(() => createGame(Number.NaN, Number.POSITIVE_INFINITY)).not.toThrow()
    expect(createGame(Number.NaN, 999).level).toBe(20)
    expect(createGame(1, -5).level).toBe(1)
  })

  it('speeds up with level', () => {
    expect(gravityMs(1)).toBe(1000)
    expect(gravityMs(10)).toBeLessThan(gravityMs(5))
    expect(gravityMs(20)).toBeGreaterThanOrEqual(16)
  })

  it('detects broken boards', () => {
    const rows = mutableBoard()
    rows[HEIGHT - 1] = Array<Cell>(WIDTH).fill('O')
    const broken: Board = rows
    expect(checkInvariants({ ...createGame(1), board: broken }).length).toBeGreaterThan(0)
  })
})

import { context, sleep } from '@reatom/core'
import { beforeEach, describe, expect, it } from 'vitest'
import { reatomTetris } from './model'

const create = (autoplay = false) =>
  reatomTetris('test', { persist: false, autoplay, seed: () => 42, strict: true })

describe('model', () => {
  beforeEach(() => {
    context.reset()
  })

  it('starts idle with an empty visible field', () => {
    const game = create()
    expect(game.status()).toBe('idle')
    expect(game.cells()).toHaveLength(200)
    expect(game.cells().every((c) => c === '')).toBe(true)
  })

  it('start / pause / resume / primary', () => {
    const game = create()
    game.primary()
    expect(game.status()).toBe('running')
    game.primary()
    expect(game.status()).toBe('paused')
    const snapshot = game.state()
    game.moveLeft()
    game.hardDrop()
    expect(game.state()).toBe(snapshot)
    game.togglePause()
    expect(game.status()).toBe('running')
  })

  it('renders active piece and ghost into cells', () => {
    const game = create()
    game.start()
    const cells = game.cells()
    expect(cells.filter((c) => c === 'ghost').length).toBeGreaterThan(0)
    expect(cells.filter((c) => c !== '' && c !== 'ghost').length).toBeGreaterThan(0)
  })

  it('tracks best score and freezes after game over', () => {
    const game = create()
    game.start(5)
    for (let i = 0; i < 100 && game.status() === 'running'; i++) game.hardDrop()
    expect(game.status()).toBe('over')
    expect(game.bestScore()).toBe(game.score())
    const snapshot = game.state()
    game.moveLeft()
    game.rotateCW()
    game.hold()
    game.tick()
    expect(game.state()).toBe(snapshot)

    game.start()
    expect(game.score()).toBe(0)
    expect(game.bestScore()).toBeGreaterThan(0)
  })

  it('exposes a 5-piece preview queue and hold', () => {
    const game = create()
    game.start()
    expect(game.queue()).toHaveLength(5)
    const first = game.state().active!.type
    game.hold()
    expect(game.held()).toBe(first)
    expect(game.canHold()).toBe(false)
  })

  it('runs gravity only while connected and running', async () => {
    const game = reatomTetris('loop', {
      persist: false,
      autoplay: true,
      seed: () => 1,
      strict: true,
    })
    game.start(20) // fastest gravity (~16ms)
    const y0 = game.state().active!.y
    const unsubscribe = game.state.subscribe(() => {})
    await sleep(120)
    expect(game.state().pieces > 0 || game.state().active!.y > y0).toBe(true)

    game.pause()
    const paused = game.state()
    await sleep(80)
    expect(game.state()).toBe(paused)

    game.resume()
    unsubscribe()
    const detached = game.state()
    await sleep(80)
    expect(game.state()).toBe(detached)
  })
})

