export const PIECE_TYPES = ['I', 'O', 'T', 'S', 'Z', 'J', 'L'] as const
export type PieceType = (typeof PIECE_TYPES)[number]
export type Rotation = 0 | 1 | 2 | 3
export type Point = readonly [x: number, y: number]

export const isPieceType = (value: unknown): value is PieceType =>
  typeof value === 'string' && (PIECE_TYPES as readonly string[]).includes(value)

/** Rotation-0 matrices (SRS spawn orientation), y grows downwards. */
const BASE_SHAPES: Record<PieceType, readonly string[]> = {
  I: ['....', '####', '....', '....'],
  O: ['##', '##'],
  T: ['.#.', '###', '...'],
  S: ['.##', '##.', '...'],
  Z: ['##.', '.##', '...'],
  J: ['#..', '###', '...'],
  L: ['..#', '###', '...'],
}

const rotateClockwise = (rows: readonly string[]): string[] => {
  const size = rows.length
  return Array.from({ length: size }, (_, y) =>
    Array.from({ length: size }, (_, x) => rows[size - 1 - x]![y]).join(''),
  )
}

const toCells = (rows: readonly string[]): Point[] => {
  const cells: Point[] = []
  rows.forEach((row, y) => {
    for (let x = 0; x < row.length; x++) if (row[x] === '#') cells.push([x, y])
  })
  return cells
}

const buildRotations = (base: readonly string[]) => {
  const result: Point[][] = []
  let rows = base
  for (let r = 0; r < 4; r++) {
    result.push(toCells(rows))
    rows = rotateClockwise(rows)
  }
  return Object.freeze(result.map((cells) => Object.freeze(cells)))
}

/** `PIECE_CELLS[type][rotation]` — occupied cells relative to the piece origin. */
export const PIECE_CELLS: Readonly<Record<PieceType, ReadonlyArray<readonly Point[]>>> =
  Object.freeze(
    Object.fromEntries(
      PIECE_TYPES.map((type) => [type, buildRotations(BASE_SHAPES[type])]),
    ) as Record<PieceType, ReadonlyArray<readonly Point[]>>,
  )

/** Size of the bounding box of the piece matrix. */
export const PIECE_SIZE: Readonly<Record<PieceType, number>> = Object.freeze(
  Object.fromEntries(PIECE_TYPES.map((t) => [t, BASE_SHAPES[t].length])) as Record<
    PieceType,
    number
  >,
)

/**
 * SRS wall kick offsets, written as in the guideline (y up) and converted to
 * y-down screen coordinates below.
 */
type KickKey = `${Rotation}>${Rotation}`
const JLSTZ_KICKS_Y_UP: Record<string, Point[]> = {
  '0>1': [[0, 0], [-1, 0], [-1, 1], [0, -2], [-1, -2]],
  '1>0': [[0, 0], [1, 0], [1, -1], [0, 2], [1, 2]],
  '1>2': [[0, 0], [1, 0], [1, -1], [0, 2], [1, 2]],
  '2>1': [[0, 0], [-1, 0], [-1, 1], [0, -2], [-1, -2]],
  '2>3': [[0, 0], [1, 0], [1, 1], [0, -2], [1, -2]],
  '3>2': [[0, 0], [-1, 0], [-1, -1], [0, 2], [-1, 2]],
  '3>0': [[0, 0], [-1, 0], [-1, -1], [0, 2], [-1, 2]],
  '0>3': [[0, 0], [1, 0], [1, 1], [0, -2], [1, -2]],
}
const I_KICKS_Y_UP: Record<string, Point[]> = {
  '0>1': [[0, 0], [-2, 0], [1, 0], [-2, -1], [1, 2]],
  '1>0': [[0, 0], [2, 0], [-1, 0], [2, 1], [-1, -2]],
  '1>2': [[0, 0], [-1, 0], [2, 0], [-1, 2], [2, -1]],
  '2>1': [[0, 0], [1, 0], [-2, 0], [1, -2], [-2, 1]],
  '2>3': [[0, 0], [2, 0], [-1, 0], [2, 1], [-1, -2]],
  '3>2': [[0, 0], [-2, 0], [1, 0], [-2, -1], [1, 2]],
  '3>0': [[0, 0], [1, 0], [-2, 0], [1, -2], [-2, 1]],
  '0>3': [[0, 0], [-1, 0], [2, 0], [-1, 2], [2, -1]],
}
const flipY = (table: Record<string, Point[]>) =>
  Object.fromEntries(
    Object.entries(table).map(([k, v]) => [k, v.map(([x, y]) => [x, -y] as Point)]),
  ) as Record<KickKey, readonly Point[]>

const JLSTZ_KICKS = flipY(JLSTZ_KICKS_Y_UP)
const I_KICKS = flipY(I_KICKS_Y_UP)
const NO_KICKS: readonly Point[] = [[0, 0]]

export const getKicks = (type: PieceType, from: Rotation, to: Rotation): readonly Point[] => {
  if (type === 'O') return NO_KICKS
  const key: KickKey = `${from}>${to}`
  return (type === 'I' ? I_KICKS : JLSTZ_KICKS)[key] ?? NO_KICKS
}

import { PIECE_TYPES, type PieceType } from './pieces'

/** mulberry32 step: pure, returns a float in [0, 1) and the next seed. */
export const nextRandom = (seed: number): [value: number, nextSeed: number] => {
  const next = (seed + 0x6d2b79f5) | 0
  let t = next
  t = Math.imul(t ^ (t >>> 15), t | 1)
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
  return [((t ^ (t >>> 14)) >>> 0) / 4294967296, next]
}

export const normalizeSeed = (seed: number): number =>
  Number.isFinite(seed) ? Math.trunc(seed) | 0 : 0

/** Fisher–Yates shuffle of a full 7-piece bag. */
export const shuffleBag = (seed: number): [bag: PieceType[], nextSeed: number] => {
  const bag: PieceType[] = [...PIECE_TYPES]
  let s = seed
  for (let i = bag.length - 1; i > 0; i--) {
    const [r, n] = nextRandom(s)
    s = n
    const j = Math.floor(r * (i + 1))
    ;[bag[i], bag[j]] = [bag[j]!, bag[i]!]
  }
  return [bag, s]
}

/**
 * Pure, framework-agnostic Tetris rules.
 *
 * Every transition is a total function `(state, ...args) => state`:
 *
 * - It never mutates its input (all structures are treated as immutable).
 * - It returns the **same reference** when nothing changes, so reactive layers
 *   can skip notifications for no-op inputs (e.g. moving into a wall).
 * - It is defensive: calling any command in the wrong status is a no-op.
 */
import {
  PIECE_CELLS,
  PIECE_SIZE,
  getKicks,
  isPieceType,
  type PieceType,
  type Rotation,
} from './pieces'
import { normalizeSeed, shuffleBag } from './random'

export const BOARD_WIDTH = 10
export const VISIBLE_HEIGHT = 20
/** Rows above the visible field where pieces spawn. */
export const HIDDEN_ROWS = 2
export const BOARD_HEIGHT = VISIBLE_HEIGHT + HIDDEN_ROWS
export const PREVIEW_SIZE = 5
export const LOCK_DELAY_MS = 500
export const MAX_LOCK_RESETS = 15
export const MIN_LEVEL = 1
export const MAX_LEVEL = 20
export const LINES_PER_LEVEL = 10

export type Cell = PieceType | null
export type Row = readonly Cell[]
export type Board = readonly Row[]
export type Status = 'idle' | 'playing' | 'paused' | 'over'

export interface ActivePiece {
  readonly type: PieceType
  readonly rotation: Rotation
  readonly x: number
  readonly y: number
  /** The last successful manipulation was a rotation (for T-spin detection). */
  readonly rotated: boolean
}

export interface ClearEvent {
  /** Monotonic id, lets UI replay an animation for identical consecutive clears. */
  readonly id: number
  readonly lines: number
  readonly tSpin: boolean
  readonly backToBack: boolean
  readonly combo: number
  readonly points: number
}

export interface GameState {
  readonly status: Status
  readonly board: Board
  readonly active: ActivePiece | null
  readonly hold: PieceType | null
  readonly canHold: boolean
  readonly queue: readonly PieceType[]
  /** Remaining pieces of the current 7-bag. */
  readonly bag: readonly PieceType[]
  readonly seed: number
  readonly startLevel: number
  readonly level: number
  readonly score: number
  readonly lines: number
  readonly placed: number
  /** -1 means "no combo running". */
  readonly combo: number
  readonly backToBack: boolean
  readonly lastClear: ClearEvent | null
  /** Incremented on each spawn; identifies the current piece. */
  readonly pieceId: number
  readonly lockResets: number
  readonly lowestY: number
}

export interface NewGameOptions {
  seed?: number
  startLevel?: number
}

// ---------------------------------------------------------------------------
// helpers

export const clampLevel = (level: number): number =>
  Number.isFinite(level)
    ? Math.min(MAX_LEVEL, Math.max(MIN_LEVEL, Math.trunc(level)))
    : MIN_LEVEL

export const levelFor = (startLevel: number, lines: number): number =>
  clampLevel(startLevel + Math.floor(lines / LINES_PER_LEVEL))

/** Guideline gravity: seconds per row = (0.8 - (level - 1) * 0.007) ^ (level - 1). */
export const gravityInterval = (level: number): number => {
  const l = clampLevel(level)
  return Math.max(16, Math.round(1000 * (0.8 - (l - 1) * 0.007) ** (l - 1)))
}

const emptyRow = (): Row => Array.from({ length: BOARD_WIDTH }, () => null)

export const createBoard = (): Board =>
  Array.from({ length: BOARD_HEIGHT }, emptyRow)

export const pieceCells = (
  piece: Pick<ActivePiece, 'type' | 'rotation' | 'x' | 'y'>,
): Array<[x: number, y: number]> =>
  PIECE_CELLS[piece.type][piece.rotation]!.map(([dx, dy]) => [piece.x + dx, piece.y + dy])

const isBlocked = (board: Board, x: number, y: number): boolean =>
  x < 0 || x >= BOARD_WIDTH || y < 0 || y >= BOARD_HEIGHT || board[y]![x] !== null

export const collides = (
  board: Board,
  piece: Pick<ActivePiece, 'type' | 'rotation' | 'x' | 'y'>,
): boolean => pieceCells(piece).some(([x, y]) => isBlocked(board, x, y))

export const isGrounded = (state: GameState): boolean =>
  state.active !== null &&
  collides(state.board, { ...state.active, y: state.active.y + 1 })

export const ghostY = (board: Board, piece: ActivePiece): number => {
  let y = piece.y
  while (!collides(board, { ...piece, y: y + 1 })) y++
  return y
}

const spawnPosition = (type: PieceType): { x: number; y: number } => ({
  x: Math.floor((BOARD_WIDTH - PIECE_SIZE[type]) / 2),
  // the first filled row of every spawn shape is its row #1 (#0 for O),
  // place it at the last hidden row so the piece peeks into the field
  y: type === 'O' ? HIDDEN_ROWS - 1 : HIDDEN_ROWS - 2,
})

/** Takes the next piece from the queue and tops the queue up from the bag. */
const drawPiece = (
  state: GameState,
): Pick<GameState, 'queue' | 'bag' | 'seed'> & { type: PieceType } => {
  let { bag, seed } = state
  const queue = [...state.queue]
  while (queue.length < PREVIEW_SIZE + 1) {
    if (bag.length === 0) [bag, seed] = shuffleBag(seed)
    queue.push(bag[0]!)
    bag = bag.slice(1)
  }
  const type = queue.shift()!
  return { type, queue, bag, seed }
}

/** Puts a piece of `type` at the spawn point, or ends the game (block out). */
const spawn = (state: GameState, type: PieceType): GameState => {
  const { x, y } = spawnPosition(type)
  for (const candidateY of [y, y - 1]) {
    const active: ActivePiece = { type, rotation: 0, x, y: candidateY, rotated: false }
    if (candidateY >= 0 && !collides(state.board, active)) {
      return {
        ...state,
        active,
        pieceId: state.pieceId + 1,
        lockResets: 0,
        lowestY: candidateY,
      }
    }
  }
  return { ...state, status: 'over', active: null }
}

const spawnNext = (state: GameState): GameState => {
  const { type, ...rest } = drawPiece(state)
  return spawn({ ...state, ...rest }, type)
}

const isTSpin = (board: Board, piece: ActivePiece): boolean => {
  if (piece.type !== 'T' || !piece.rotated) return false
  const corners = [
    [piece.x, piece.y],
    [piece.x + 2, piece.y],
    [piece.x, piece.y + 2],
    [piece.x + 2, piece.y + 2],
  ] as const
  return corners.filter(([x, y]) => isBlocked(board, x, y)).length >= 3
}

const LINE_POINTS = [0, 100, 300, 500, 800] as const
const T_SPIN_POINTS = [400, 800, 1200, 1600] as const

/** Merges the active piece into the board, clears lines, scores, spawns next. */
const lock = (state: GameState): GameState => {
  const piece = state.active
  if (!piece) return state
  const cells = pieceCells(piece)
  const tSpin = isTSpin(state.board, piece)

  const merged = state.board.map((row) => [...row])
  for (const [x, y] of cells) merged[y]![x] = piece.type

  // lock out: the piece landed completely above the visible field
  if (cells.every(([, y]) => y < HIDDEN_ROWS)) {
    return { ...state, board: merged, active: null, status: 'over', placed: state.placed + 1 }
  }

  const kept = merged.filter((row) => row.some((cell) => cell === null))
  const cleared = BOARD_HEIGHT - kept.length
  const board: Board = [
    ...Array.from({ length: cleared }, emptyRow),
    ...kept,
  ]

  const difficult = cleared === 4 || (tSpin && cleared > 0)
  const combo = cleared > 0 ? state.combo + 1 : -1
  let points = (tSpin ? T_SPIN_POINTS[cleared]! : LINE_POINTS[cleared]!) * state.level
  const backToBackBonus = difficult && state.backToBack
  if (backToBackBonus) points = Math.floor(points * 1.5)
  if (combo > 0) points += 50 * combo * state.level

  const lines = state.lines + cleared
  const lastClear: ClearEvent | null =
    cleared > 0 || tSpin
      ? {
          id: (state.lastClear?.id ?? 0) + 1,
          lines: cleared,
          tSpin,
          backToBack: backToBackBonus,
          combo,
          points,
        }
      : state.lastClear

  return spawnNext({
    ...state,
    board,
    active: null,
    canHold: true,
    score: state.score + points,
    lines,
    level: levelFor(state.startLevel, lines),
    placed: state.placed + 1,
    combo,
    backToBack: cleared > 0 ? difficult : state.backToBack,
    lastClear,
  })
}

/** Lock-delay bookkeeping after a successful move / rotation ("move reset"). */
const afterManipulation = (prev: GameState, next: GameState): GameState => {
  const piece = next.active!
  if (piece.y > next.lowestY) {
    return { ...next, lowestY: piece.y, lockResets: 0 }
  }
  if (!isGrounded(prev) && !isGrounded(next)) return next
  const lockResets = Math.min(MAX_LOCK_RESETS, next.lockResets + 1)
  const result = { ...next, lockResets }
  // the reset budget is exhausted: lock as soon as the piece touches ground
  return lockResets >= MAX_LOCK_RESETS && isGrounded(result) ? lock(result) : result
}

const canControl = (
  state: GameState,
): state is GameState & { active: ActivePiece } =>
  state.status === 'playing' && state.active !== null

// ---------------------------------------------------------------------------
// public transitions

export const createGame = (options: NewGameOptions = {}): GameState => {
  const seed = normalizeSeed(options.seed ?? 0)
  const startLevel = clampLevel(options.startLevel ?? MIN_LEVEL)
  const base: GameState = {
    status: 'idle',
    board: createBoard(),
    active: null,
    hold: null,
    canHold: true,
    queue: [],
    bag: [],
    seed,
    startLevel,
    level: startLevel,
    score: 0,
    lines: 0,
    placed: 0,
    combo: -1,
    backToBack: false,
    lastClear: null,
    pieceId: 0,
    lockResets: 0,
    lowestY: 0,
  }
  // prefill the preview queue so it is visible before the start
  const { type, queue, bag, seed: nextSeed } = drawPiece(base)
  return { ...base, queue: [type, ...queue].slice(0, PREVIEW_SIZE), bag: [...queue.slice(PREVIEW_SIZE - 1), ...bag], seed: nextSeed }
}

/** Starts a fresh game. The random sequence continues from the previous state unless a seed is given. */
export const startGame = (state: GameState, options: NewGameOptions = {}): GameState => {
  const fresh =
    options.seed === undefined
      ? createGame({ seed: state.seed, startLevel: options.startLevel ?? state.startLevel })
      : createGame({ seed: options.seed, startLevel: options.startLevel ?? state.startLevel })
  return spawnNext({ ...fresh, status: 'playing' })
}

export const pauseGame = (state: GameState): GameState =>
  state.status === 'playing' ? { ...state, status: 'paused' } : state

export const resumeGame = (state: GameState): GameState =>
  state.status === 'paused' ? { ...state, status: 'playing' } : state

export const togglePause = (state: GameState): GameState =>
  state.status === 'playing' ? pauseGame(state) : resumeGame(state)

export const move = (state: GameState, dx: -1 | 1): GameState => {
  if (!canControl(state)) return state
  const active = { ...state.active, x: state.active.x + dx, rotated: false }
  if (collides(state.board, active)) return state
  return afterManipulation(state, { ...state, active })
}

export const rotate = (state: GameState, direction: 1 | -1): GameState => {
  if (!canControl(state) || state.active.type === 'O') return state
  const from = state.active.rotation
  const to = ((from + direction + 4) % 4) as Rotation
  for (const [kx, ky] of getKicks(state.active.type, from, to)) {
    const active: ActivePiece = {
      ...state.active,
      rotation: to,
      x: state.active.x + kx,
      y: state.active.y + ky,
      rotated: true,
    }
    if (!collides(state.board, active)) {
      return afterManipulation(state, { ...state, active })
    }
  }
  return state
}

/** One row down by the player, +1 point. Does not lock (lock delay does). */
export const softDrop = (state: GameState): GameState => {
  if (!canControl(state) || isGrounded(state)) return state
  const active = { ...state.active, y: state.active.y + 1, rotated: false }
  return afterManipulation(state, { ...state, active, score: state.score + 1 })
}

export const hardDrop = (state: GameState): GameState => {
  if (!canControl(state)) return state
  const y = ghostY(state.board, state.active)
  const distance = y - state.active.y
  const active = distance > 0 ? { ...state.active, y, rotated: false } : state.active
  return lock({ ...state, active, score: state.score + distance * 2 })
}

/** Gravity step: fall one row, or lock if the piece rests on something. */
export const tick = (state: GameState): GameState => {
  if (!canControl(state)) return state
  if (isGrounded(state)) return lock(state)
  const active = { ...state.active, y: state.active.y + 1, rotated: false }
  const next = { ...state, active }
  return active.y > state.lowestY ? { ...next, lowestY: active.y, lockResets: 0 } : next
}

export const holdPiece = (state: GameState): GameState => {
  if (!canControl(state) || !state.canHold) return state
  const current = state.active.type
  const base = { ...state, hold: current, canHold: false, active: null }
  return state.hold === null ? spawnNext(base) : spawn(base, state.hold)
}

// ---------------------------------------------------------------------------
// invariants

/** Returns a list of broken invariants; an empty list means the state is consistent. */
export const validateState = (state: GameState): string[] => {
  const errors: string[] = []
  const isNonNegativeInt = (n: unknown) => Number.isInteger(n) && (n as number) >= 0

  if (!['idle', 'playing', 'paused', 'over'].includes(state.status)) {
    errors.push(`unknown status "${state.status}"`)
  }
  if (state.board.length !== BOARD_HEIGHT) errors.push('board height mismatch')
  state.board.forEach((row, y) => {
    if (row.length !== BOARD_WIDTH) errors.push(`row ${y} width mismatch`)
    if (row.some((cell) => cell !== null && !isPieceType(cell))) {
      errors.push(`row ${y} has an invalid cell`)
    }
    if (state.status !== 'over' && row.every((cell) => cell !== null)) {
      errors.push(`row ${y} is full but not cleared`)
    }
  })
  if (state.status === 'playing' || state.status === 'paused') {
    if (!state.active) errors.push(`no active piece while ${state.status}`)
    else if (collides(state.board, state.active)) errors.push('active piece overlaps the board')
  }
  if (state.status === 'idle' && state.active) errors.push('active piece while idle')
  if (state.queue.length !== PREVIEW_SIZE || !state.queue.every(isPieceType)) {
    errors.push('invalid preview queue')
  }
  if (state.bag.length > 7 || new Set(state.bag).size !== state.bag.length) {
    errors.push('invalid bag')
  }
  if (state.hold !== null && !isPieceType(state.hold)) errors.push('invalid hold')
  for (const key of ['score', 'lines', 'placed', 'pieceId', 'lockResets'] as const) {
    if (!isNonNegativeInt(state[key])) errors.push(`${key} must be a non-negative integer`)
  }
  if (state.lockResets > MAX_LOCK_RESETS) errors.push('lock resets overflow')
  if (state.level !== levelFor(state.startLevel, state.lines)) errors.push('level mismatch')
  return errors
}

